import { supabase } from './supabase-client.js';
import { listInventoryItems, createInventoryItemQuick, createWarehouseReceiptObjectV2 } from './wr-data-v2.js?v=20260909-v10';

const main=document.getElementById('main');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TYPES=['PALLET','SKID','CRATE','CARTON','BOX','DRUM','BAG','PIECE','OTHER'];
const TYPE_UOM={PALLET:'PLT',SKID:'SKD',CRATE:'CRT',CARTON:'CTN',BOX:'BOX',DRUM:'DRM',BAG:'BAG',PIECE:'EA',OTHER:'EA'};
const REF_TYPES=['BOL','PRO','TRACKING'];
const EXCEPTIONS=[['DAMAGE','Damage'],['SHORTAGE','Shortage'],['OVERAGE','Overage'],['WET','Wet cargo'],['OPEN_PACKAGE','Open package'],['SEAL_DISCREPANCY','Seal discrepancy'],['HOLD','Hold'],['DG','Dangerous goods'],['IN_BOND_7512','In-bond / 7512']];
const STEPS=[['checkin','Check in','Driver + reference'],['cargo','Receive cargo','Count · inspect · measure'],['evidence','Evidence','Photos + documents'],['checkout','Check out','Sign + time out'],['putaway','Put away','Label + scan location'],['complete','Complete','Close receipt']];

const css=document.createElement('style');css.textContent=`
.wros{max-width:1100px;margin:0 auto;padding-bottom:120px}.wros-hero{border:1px solid #27364b;border-radius:22px;background:linear-gradient(150deg,#121c2b,#0b1119);padding:18px;margin-bottom:14px}.wros-hero-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.wros-hero h1{margin:2px 0;font-size:28px}.wros-hero p{margin:4px 0 0;color:var(--muted);font-size:12px}.wros-state{border:1px solid #35577f;border-radius:999px;padding:6px 9px;font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:#acd0ff;white-space:nowrap}.wros-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px}.wros-metric{border:1px solid #26354a;border-radius:14px;padding:10px;background:#0c121a}.wros-metric span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.wros-metric b{display:block;margin-top:3px;font-size:14px}.wros-steps{display:flex;gap:7px;overflow-x:auto;margin-top:14px;padding-bottom:2px}.wros-step{min-width:135px;border:1px solid #28374c;border-radius:14px;padding:10px;background:#0b1118;color:var(--muted);text-align:left}.wros-step b{display:block;font-size:11px}.wros-step small{display:block;margin-top:2px;font-size:9px;color:inherit}.wros-step.done{color:#76d6aa;border-color:#2d6651}.wros-step.active{color:white;border-color:#3d82da;background:#142640}.wros-card{border:1px solid #26364b;border-radius:20px;background:#0c1118;padding:18px;margin-bottom:14px}.wros-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:16px}.wros-head h2{margin:0;font-size:22px}.wros-head p{margin:4px 0 0;color:var(--muted);font-size:12px}.wros-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wros-grid .span2{grid-column:1/-1}.wros-field{display:block}.wros-field>span{display:block;color:#cfd8e5;font-size:11px;margin-bottom:5px}.wros-field input,.wros-field select,.wros-field textarea{width:100%;box-sizing:border-box}.wros-details{border-top:1px solid var(--border);margin-top:14px;padding-top:12px}.wros-details summary{color:var(--muted);cursor:pointer;font-size:12px}.wros-bar{position:fixed;left:max(16px,calc((100vw - 1100px)/2));right:max(16px,calc((100vw - 1100px)/2));bottom:calc(76px + env(safe-area-inset-bottom));z-index:85;border:1px solid #2b3c54;border-radius:18px;background:rgba(8,13,20,.94);backdrop-filter:blur(18px);padding:9px;display:flex;gap:8px}.wros-bar button{min-height:48px}.wros-grow{flex:1}.wros-table-wrap{overflow:auto;border:1px solid #26354a;border-radius:16px}.wros-table{border-collapse:collapse;width:100%;min-width:900px}.wros-table th,.wros-table td{padding:10px;border-bottom:1px solid #202d3e;text-align:left;font-size:11px;vertical-align:middle}.wros-table th{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.wros-tree{display:flex;align-items:center;gap:8px;min-width:190px}.wros-indent{width:calc(var(--depth) * 18px);flex:0 0 auto}.wros-guide{width:3px;align-self:stretch;min-height:28px;border-radius:4px;background:linear-gradient(#2f7af7,#28c6c8)}.wros-tree small{display:block;color:var(--muted);margin-top:2px}.wros-actions{display:flex;gap:5px;flex-wrap:wrap;min-width:230px}.wros-actions button{padding:7px 9px}.wros-toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px}.wros-toolbar .muted{font-size:11px}.wros-drawer-back{position:fixed;inset:0;z-index:180;background:#0008}.wros-drawer{position:fixed;right:0;top:0;bottom:0;z-index:181;width:min(560px,94vw);overflow:auto;background:#0b1119;border-left:1px solid #2b3d55;padding:18px 18px 120px;box-shadow:-22px 0 60px #000a}.wros-drawer-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.wros-drawer-head h2{margin:2px 0}.wros-path{border:1px solid #283b54;border-radius:14px;padding:10px;margin-bottom:12px;background:#0e1723}.wros-node{position:relative;display:block;width:100%;border:0;background:transparent;color:var(--muted);text-align:left;padding:7px 8px 7px calc(14px + var(--depth)*18px);border-radius:9px}.wros-node:before{content:'';position:absolute;left:calc(8px + var(--depth)*18px);top:5px;bottom:5px;width:2px;border-radius:2px;background:#337de9}.wros-node.active{background:#152943;color:white}.wros-live{position:sticky;bottom:0;border:1px solid #31577f;border-radius:14px;padding:10px;background:rgba(10,18,28,.96);display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px}.wros-live span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.08em}.wros-live b{display:block;font-size:12px;margin-top:2px}.wros-quick{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.wros-chiprow{display:flex;gap:7px;flex-wrap:wrap}.wros-chip{border:1px solid #2d4058;border-radius:999px;padding:8px 11px;background:#0c131c;color:var(--muted);font-size:10px}.wros-chip.active{border-color:#4c84cf;background:#162a44;color:white}.wros-chip.danger.active{border-color:#98515b;background:#2a171b;color:#ffdfe1}.wros-timeline{display:grid;gap:8px}.wros-event{border:1px solid #26364a;border-radius:14px;padding:11px;display:flex;justify-content:space-between;gap:12px}.wros-event span{color:var(--muted);font-size:10px}.wros-event b{font-size:12px}.wros-empty{border:1px dashed #2b3b50;border-radius:16px;padding:18px;color:var(--muted);text-align:center}.wros-good{color:#77d8ab}.wros-warn{color:#ffcd7b}.wros-put-row{display:grid;grid-template-columns:1.5fr 1fr auto;gap:8px;align-items:center;border-bottom:1px solid #1f2d3e;padding:10px 0}.wros-put-row:last-child{border-bottom:0}.wros-select{border:1px solid #2a3a50;border-radius:14px;padding:10px;margin-top:10px}.wros-exception{border:1px solid #56333b;background:#1d1115;border-radius:14px;padding:10px;margin-top:8px}.wros-exception b{display:block;color:#ffd8dd}.wros-doc-row{display:flex;justify-content:space-between;gap:10px;align-items:center;border-bottom:1px solid #1e2b3b;padding:10px 0}.wros-doc-row small{color:var(--muted)}.wros-setup-cargo{display:grid;grid-template-columns:1.3fr .7fr;gap:10px}.wros-inline-note{font-size:10px;color:var(--muted);margin-top:5px}.wros-hidden{display:none!important}
@media(max-width:760px){.wros{margin:0 10px}.wros-hero,.wros-card{padding:14px}.wros-grid{grid-template-columns:1fr}.wros-grid .span2{grid-column:auto}.wros-metrics{grid-template-columns:1fr 1fr}.wros-bar{left:10px;right:10px}.wros-drawer{left:0;right:0;top:auto;width:auto;height:82vh;border-left:0;border-top:1px solid #2b3d55;border-radius:24px 24px 0 0}.wros-live{grid-template-columns:1fr 1fr}.wros-put-row{grid-template-columns:1fr}.wros-quick{grid-template-columns:1fr}.wros-head{display:block}.wros-state{display:inline-block;margin-top:8px}.wros-setup-cargo{grid-template-columns:1fr}}
`;document.head.appendChild(css);

let S=null;
const temp=()=>`tmp-${crypto.randomUUID?.()||Date.now()+Math.random()}`;
const fmt=v=>v?new Date(v).toLocaleString():'—';
const num=v=>v==null||v===''?null:Number(v);
const roots=()=>S.cargo.filter(x=>!x.parent_id);
const children=id=>S.cargo.filter(x=>x.parent_id===id);
function flat(){const out=[];const walk=(x,d)=>{out.push({x,depth:d});children(x.id).forEach(c=>walk(c,d+1))};roots().forEach(r=>walk(r,0));return out}
function rootOf(x){let cur=x;while(cur?.parent_id){cur=S.cargo.find(y=>y.id===cur.parent_id)||cur;if(!cur.parent_id)break}return cur}
function partLabel(p){return [p.part_number,p.sku,p.description].filter(Boolean).join(' · ')||'Part'}
function cargoMetrics(){let handling=0,weight=0,volume=0,pieces=0;for(const x of roots()){const q=Number(x.quantity||0);handling+=q;weight+=Number(x.weight_lb||0);if([x.length_in,x.width_in,x.height_in].every(v=>Number(v)>0))volume+=Number(x.length_in)*Number(x.width_in)*Number(x.height_in)*0.000016387064*q}for(const x of S.cargo)if(!children(x.id).length)pieces+=Number(x.quantity||0);return{handling,weight,volume,pieces}}
function stage(){if(!S.wr)return'setup';const v=S.visit;const located=roots().length>0&&roots().every(x=>x.current_location_id||x.warehouse_location_id);if(!v?.time_in)return'checkin';if(!v.operation_completed_at)return'cargo';if(!v.time_out)return'checkout';if(!located)return'putaway';if(S.wr.status!=='completed')return'complete';return'complete'}
function stepDone(k){if(!S.wr)return false;const v=S.visit;const located=roots().length>0&&roots().every(x=>x.current_location_id||x.warehouse_location_id);if(k==='checkin')return !!v?.time_in;if(k==='cargo')return !!v?.operation_completed_at;if(k==='evidence')return S.docs.length>0;if(k==='checkout')return !!v?.time_out;if(k==='putaway')return located;if(k==='complete')return S.wr.status==='completed';return false}
function setStep(k){S.step=k;render()}

async function loadReferenceData(){const [e,p,l]=await Promise.all([supabase.from('entities').select('id,name,code,roles').order('name').limit(700),listInventoryItems(),supabase.from('warehouse_locations').select('id,code,name,zone,active').eq('active',true).order('code').limit(5000)]);if(e.error)throw e.error;if(l.error)throw l.error;S.entities=e.data||[];S.parts=p||[];S.locations=l.data||[]}
async function transactionId(wrId){const{data}=await supabase.from('transactions').select('id').eq('transaction_type','WAREHOUSE_RECEIPT').eq('domain_record_id',wrId).maybeSingle();return data?.id||null}
async function loadSaved(wrId){const{data:wr,error}=await supabase.from('warehouse_receipts').select('id,organization_id,job_id,receipt_number,status,started_at,completed_at,created_at').eq('id',wrId).single();if(error)throw error;const[{data:job},{data:refs},{data:parties},{data:cargo},{data:visits},{data:flags},{data:docs}]=await Promise.all([supabase.from('jobs').select('id,customer_id,description').eq('id',wr.job_id).single(),supabase.from('shipment_references').select('*').eq('warehouse_receipt_id',wr.id).order('created_at'),supabase.from('warehouse_receipt_parties').select('*').eq('warehouse_receipt_id',wr.id),supabase.from('cargo_units').select('*').eq('job_id',wr.job_id).order('created_at'),supabase.from('warehouse_visits').select('*').eq('warehouse_receipt_id',wr.id).eq('direction','inbound').order('created_at',{ascending:false}),supabase.from('operational_flags').select('*').eq('warehouse_receipt_id',wr.id).eq('active',true),supabase.from('documents').select('id,display_name,file_name,category,mime_type,created_at,cargo_object_id,metadata').eq('transaction_id',await transactionId(wr.id)).eq('is_current',true).order('created_at',{ascending:false})]);S.wr=wr;S.job=job;S.refs=refs||[];S.partiesRows=parties||[];S.cargo=cargo||[];S.visit=visits?.[0]||null;S.flags=flags||[];S.docs=docs||[];S.customer_id=job?.customer_id||'';S.description=job?.description||'';S.customer_ref=(refs||[]).find(x=>x.is_primary)?.reference_value||(refs||[])[0]?.reference_value||'';S.tx=await transactionId(wr.id);S.step=stage()}

function hero(){const m=cargoMetrics(),customer=S.entities.find(x=>x.id===S.customer_id),state=S.wr?S.wr.status:'New';return `<section class="wros-hero"><div class="wros-hero-top"><div><div class="eyebrow">WAREHOUSE RECEIVING</div><h1 class="txw-title">${esc(S.wr?.receipt_number||'New receipt')}</h1><p>${esc(customer?.name||'Fast create, then continue receiving in the same workspace.')}${S.customer_ref?` · ${esc(S.customer_ref)}`:''}</p></div><span class="wros-state">${esc(state)}</span></div><div class="wros-metrics"><div class="wros-metric"><span>Handling units</span><b>${m.handling}</b></div><div class="wros-metric"><span>Gross weight</span><b>${m.weight.toLocaleString()} LB</b></div><div class="wros-metric"><span>Volume</span><b>${m.volume.toFixed(4)} CBM</b></div><div class="wros-metric"><span>Evidence</span><b>${S.docs.length}</b></div></div>${S.wr?`<div class="wros-steps">${STEPS.map(([k,l,h])=>`<button type="button" class="wros-step ${stepDone(k)?'done':''} ${S.step===k?'active':''}" data-step="${k}"><b>${stepDone(k)?'✓ ':''}${l}</b><small>${h}</small></button>`).join('')}</div>`:''}</section>`}
function entityOptions(){return S.entities.map(x=>`<option value="${esc(x.name)}">${esc(x.code||'')}</option>`).join('')}
function partOptions(){return S.parts.map(x=>`<option value="${esc(partLabel(x))}"></option>`).join('')}

function setup(){return `<section class="wros-card"><div class="wros-head"><div><h2>Create the WR fast</h2><p>Only the customer, one reference and the outer physical cargo are needed to start. Everything else continues on the same record.</p></div><span class="wros-state">30-second start</span></div><div class="wros-grid"><label class="wros-field"><span>Customer *</span><input id="wros-customer" list="wros-customer-list" placeholder="Type customer name…" value="${esc(S.customer_name||'')}"><datalist id="wros-customer-list">${S.entities.map(x=>`<option value="${esc(x.name)}">${esc(x.code||'')}</option>`).join('')}</datalist></label><label class="wros-field"><span>Customer / inbound reference *</span><input id="wros-ref" value="${esc(S.customer_ref||'')}" placeholder="PO, SO, BOL, booking…"></label><label class="wros-field span2"><span>Description / commodity</span><input id="wros-desc" value="${esc(S.description||'')}" placeholder="What is being received?"></label></div><div class="wros-details"><b>Outer cargo</b><div class="wros-inline-note">Use what physically arrives at the dock: pallet, box, crate, piece, etc. You can build the nested contents immediately after the WR starts.</div><div class="wros-setup-cargo" style="margin-top:10px"><label class="wros-field"><span>Package type</span><select id="wros-start-type">${TYPES.map(t=>`<option ${t===S.start_type?'selected':''}>${t}</option>`).join('')}</select></label><label class="wros-field"><span>Quantity</span><input id="wros-start-qty" type="number" min="1" value="${S.start_qty||1}"></label></div></div><div class="wros-chiprow" style="margin-top:14px">${[['DG','DG'],['IN_BOND_7512','7512 / in-bond'],['HOLD','Hold']].map(([k,l])=>`<button type="button" class="wros-chip ${S.draftFlags.includes(k)?'active':''}" data-draft-flag="${k}">${l}</button>`).join('')}</div></section>`}

function checkin(){const v=S.visit||{};if(v.time_in)return `<section class="wros-card"><div class="wros-head"><div><h2 class="wros-good">✓ Driver checked in</h2><p>${esc(v.carrier_name_snapshot||'Carrier')} · ${esc(v.driver_name||'Driver')} · ${esc(v.bol_number||v.pro_number||v.tracking_number||'No reference')}</p></div><span class="wros-state">${esc(fmt(v.time_in))}</span></div><div class="wros-timeline"><div class="wros-event"><b>Government ID</b><span>${v.driver_id_verified?'Verified':'Not verified'}</span></div><div class="wros-event"><b>STA / TSA</b><span>${v.sta_verified?'Verified / not required':'Pending'}</span></div></div><div class="wros-quick" style="margin-top:12px"><button class="secondary" data-sign="checkin">✍ Driver sign-in</button><button class="secondary" data-scan-doc="BOL">▣ Scan BOL / receiving document</button></div></section>`;return `<section class="wros-card"><div class="wros-head"><div><h2>1. Check in the driver</h2><p>Capture who arrived, what movement they represent, and the compliance checks before unloading.</p></div><span class="wros-state">Time in is automatic</span></div><datalist id="wros-carriers">${entityOptions()}</datalist><div class="wros-grid"><label class="wros-field"><span>Carrier *</span><input id="wros-carrier" list="wros-carriers" placeholder="Type carrier…"></label><label class="wros-field"><span>Driver name *</span><input id="wros-driver" placeholder="Driver name"></label><label class="wros-field"><span>Name on government ID</span><input id="wros-id-name" placeholder="As shown on ID"></label><label class="wros-field"><span>Reference type *</span><select id="wros-ref-type">${REF_TYPES.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="wros-field span2"><span>BOL / PRO / tracking *</span><input id="wros-move-ref" placeholder="Type or scan reference"></label><label class="wros-field"><span><input type="checkbox" id="wros-id-ok"> Government ID verified</span></label><label class="wros-field"><span><input type="checkbox" id="wros-sta-ok"> STA verified / not required</span></label></div><details class="wros-details"><summary>Equipment / security details</summary><div class="wros-grid" style="margin-top:10px"><label class="wros-field"><span>Trailer / container</span><input id="wros-trailer"></label><label class="wros-field"><span>Truck / tractor</span><input id="wros-tractor"></label><label class="wros-field"><span>Seal</span><input id="wros-seal"></label><label class="wros-field"><span>Dock / door</span><input id="wros-door"></label></div></details><div class="wros-quick" style="margin-top:12px"><button class="secondary" data-scan-doc="BOL">▣ Scan BOL / receiving document</button><button class="primary" id="wros-checkin">Check in now →</button></div></section>`}

function cargoTable(){return `<section class="wros-card"><div class="wros-head"><div><h2>2. Receive cargo</h2><p>Count, inspect, measure and build the physical hierarchy without losing sight of the whole shipment.</p></div><span class="wros-state">${roots().length} top-level</span></div><div class="wros-toolbar"><div class="muted">Tap any nested level to edit it. Package type determines its count unit.</div><button class="primary" id="wros-add-root">＋ Add cargo</button></div>${S.cargo.length?`<div class="wros-table-wrap"><table class="wros-table"><thead><tr><th>Cargo</th><th>Qty</th><th>Part / SKU</th><th>Weight</th><th>Dimensions</th><th>Location</th><th>Actions</th></tr></thead><tbody>${flat().map(({x,depth})=>{const loc=S.locations.find(l=>l.id===(rootOf(x)?.current_location_id||rootOf(x)?.warehouse_location_id));return `<tr><td><button type="button" class="wros-node" style="--depth:${depth}" data-edit="${x.id}"><b>${esc(x.description||x.package_type)}</b><small>${depth?`Contained level ${depth}`:'Handling level'} · ${esc(x.package_type||'')}</small></button></td><td>${Number(x.quantity||0)} ${esc(x.uom||TYPE_UOM[x.package_type]||'')}</td><td>${esc(x.part_number||x.sku||'—')}</td><td>${x.weight_lb?`${Number(x.weight_lb)} lb`:'—'}</td><td>${[x.length_in,x.width_in,x.height_in].every(v=>Number(v)>0)?`${x.length_in}×${x.width_in}×${x.height_in} in`:'—'}</td><td>${esc(loc?.code||'—')}</td><td><div class="wros-actions"><button class="secondary" data-edit="${x.id}">Edit</button><button class="secondary" data-copy="${x.id}">Copy</button><button class="secondary" data-child="${x.id}">＋ Inside</button><button class="secondary" data-photo="${x.id}">📷</button></div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="wros-empty">No cargo records yet.</div>'}<div class="wros-quick" style="margin-top:12px"><button class="secondary" id="wros-exception">⚠ Add exception / discrepancy</button>${!S.visit?.operation_completed_at?'<button class="primary" id="wros-unload-complete">Finish unloading →</button>':'<button class="secondary" disabled>✓ Unloading complete</button>'}</div>${S.flags.length?`<div style="margin-top:12px"><b>Open exceptions</b>${S.flags.map(f=>`<div class="wros-exception"><b>${esc(f.flag_type.replaceAll('_',' '))}</b><span>${esc(f.notes||'')}</span></div>`).join('')}</div>`:''}</section>`}

function evidence(){return `<section class="wros-card"><div class="wros-head"><div><h2>3. Evidence & documents</h2><p>Capture cargo-condition photos and scan paperwork without leaving receiving.</p></div><span class="wros-state">${S.docs.length} files</span></div><div class="wros-quick"><button class="primary" id="wros-camera">📷 Cargo photo set</button><button class="secondary" id="wros-scan">▣ Multi-page scanner</button><button class="secondary" id="wros-upload">↑ Upload files</button><input id="wros-upload-input" type="file" multiple hidden accept="image/*,application/pdf"></div>${S.docs.length?`<div style="margin-top:12px">${S.docs.map(d=>`<div class="wros-doc-row"><div><b>${esc(d.display_name||d.file_name||d.category)}</b><small>${esc(d.category||'DOCUMENT')} · ${esc(fmt(d.created_at))}</small></div><span>${d.cargo_object_id?'Cargo evidence':'WR'}</span></div>`).join('')}</div>`:'<div class="wros-empty" style="margin-top:12px">No evidence attached yet.</div>'}</section>`}

function checkout(){const v=S.visit||{},signed=S.checkoutSigned;return `<section class="wros-card"><div class="wros-head"><div><h2>4. Driver check-out</h2><p>Review the handoff, capture departure acknowledgement, then record the actual time out.</p></div><span class="wros-state">${v.time_out?fmt(v.time_out):'Driver on site'}</span></div><div class="wros-timeline"><div class="wros-event"><b>Time in</b><span>${esc(fmt(v.time_in))}</span></div><div class="wros-event"><b>Unload complete</b><span>${esc(fmt(v.operation_completed_at))}</span></div><div class="wros-event"><b>Exceptions</b><span>${S.flags.length}</span></div><div class="wros-event"><b>Departure signature</b><span>${signed?'Captured':'Pending'}</span></div></div>${v.time_out?'<div class="notice good" style="margin-top:12px">Driver visit is closed.</div>':`<div class="wros-quick" style="margin-top:12px"><button class="secondary" data-sign="checkout">✍ Driver sign-out</button><button class="primary" id="wros-checkout">${signed?'Check out driver →':'Sign & check out →'}</button></div>`}</section>`}

function putaway(){return `<section class="wros-card"><div class="wros-head"><div><h2>5. Labels & put-away</h2><p>Print the warehouse labels, then scan the cargo label and the destination location. Manual selection remains available.</p></div><span class="wros-state">${roots().filter(x=>x.current_location_id||x.warehouse_location_id).length}/${roots().length} located</span></div><div class="wros-quick"><button class="primary" id="wros-labels">▣ Print 4×6 labels</button><button class="secondary" id="wros-scan-cargo">Scan cargo label</button><button class="secondary" id="wros-scan-location">Scan location</button></div><div class="wros-select"><b>Selected cargo</b><div id="wros-selected-cargo" class="muted" style="margin-top:4px">${esc(S.selectedCargo?`${S.selectedCargo.handling_unit_code||S.selectedCargo.uin||S.selectedCargo.description||S.selectedCargo.package_type}`:'None — scan or tap a row below')}</div></div><div style="margin-top:10px">${roots().map(x=>{const loc=S.locations.find(l=>l.id===(x.current_location_id||x.warehouse_location_id));return `<div class="wros-put-row"><button class="secondary" data-select-cargo="${x.id}">${esc(x.handling_unit_code||x.uin||x.description||x.package_type)} · ${Number(x.quantity||0)} ${esc(x.uom||'')}</button><select data-location-for="${x.id}"><option value="">Choose location…</option>${S.locations.map(l=>`<option value="${l.id}" ${(x.current_location_id||x.warehouse_location_id)===l.id?'selected':''}>${esc(l.code)}${l.zone?` · ${esc(l.zone)}`:''}</option>`).join('')}</select><button class="primary" data-assign="${x.id}">${loc?'Move':'Assign'}</button></div>`}).join('')}</div></section>`}

function complete(){const m=cargoMetrics(),v=S.visit||{};return `<section class="wros-card"><div class="wros-head"><div><h2>${S.wr.status==='completed'?'✓ Receipt complete':'6. Complete the Warehouse Receipt'}</h2><p>Generate the customer-facing receipt, retain the evidence, and close operational custody.</p></div><span class="wros-state">${esc(S.wr.status)}</span></div><div class="wros-metrics"><div class="wros-metric"><span>Handling</span><b>${m.handling}</b></div><div class="wros-metric"><span>Weight</span><b>${m.weight} LB</b></div><div class="wros-metric"><span>Volume</span><b>${m.volume.toFixed(4)} CBM</b></div><div class="wros-metric"><span>Time out</span><b>${v.time_out?new Date(v.time_out).toLocaleTimeString(): '—'}</b></div></div><div class="wros-quick" style="margin-top:12px"><button class="secondary" id="wros-pdf">↓ Warehouse Receipt PDF</button><button class="secondary" id="wros-labels2">▣ Reprint labels</button>${S.wr.status!=='completed'?'<button class="primary" id="wros-complete">Complete WR</button>':'<button class="secondary" disabled>✓ Completed</button>'}</div></section>`}

function content(){if(!S.wr)return setup();if(S.step==='checkin')return checkin();if(S.step==='cargo')return cargoTable();if(S.step==='evidence')return evidence();if(S.step==='checkout')return checkout();if(S.step==='putaway')return putaway();return complete()}
function bar(){if(!S.wr)return `<div class="wros-bar"><button class="secondary" id="wros-cancel">Cancel</button><button class="primary wros-grow" id="wros-start">Create WR & start receiving →</button></div>`;const i=STEPS.findIndex(x=>x[0]===S.step),prev=i>0?STEPS[i-1][0]:null,next=i<STEPS.length-1?STEPS[i+1][0]:null;return `<div class="wros-bar">${prev?'<button class="secondary" id="wros-prev">← Back</button>':'<button class="secondary" id="wros-list">Receipts</button>'}<button class="secondary" id="wros-skip">Skip for now</button>${next?'<button class="primary wros-grow" id="wros-next">Continue →</button>':'<button class="primary wros-grow" id="wros-pdfbar">WR PDF</button>'}</div>`}
function render(){window.nodaraSetActive?.('wr');main.classList.remove('txw-active');main.dataset.wrCanonical='1';main.innerHTML=`<div class="wros">${hero()}${content()}${bar()}</div>`;bind()}

function syncSetup(){const customer=document.getElementById('wros-customer')?.value.trim()||'';S.customer_name=customer;S.customer_id=S.entities.find(x=>x.name.toLowerCase()===customer.toLowerCase())?.id||'';S.customer_ref=document.getElementById('wros-ref')?.value.trim()||'';S.description=document.getElementById('wros-desc')?.value.trim()||'';S.start_type=document.getElementById('wros-start-type')?.value||'PALLET';S.start_qty=Math.max(1,Number(document.getElementById('wros-start-qty')?.value||1))}
async function startReceiving(){syncSetup();if(!S.customer_id)return alert('Choose an existing customer.');if(!S.customer_ref)return alert('Enter the customer or inbound reference.');const btn=document.getElementById('wros-start');btn.disabled=true;btn.textContent='Creating…';try{const type=S.start_type||'PALLET',tree=[{type,quantity:S.start_qty||1,uom:TYPE_UOM[type]||'EA',description:S.description||type,condition:'good',children:[]}],parties={customer:{entity_id:S.customer_id}},flags=S.draftFlags.map(type=>({type,severity:'info',active:true,source:'manual'}));const r=await createWarehouseReceiptObjectV2({customer_id:S.customer_id,description:S.description,references:[{type:'CUSTOMER_REF',value:S.customer_ref,primary:true}],parties,flags,tree});await supabase.from('warehouse_receipts').update({status:'receiving',started_at:null,completed_at:null}).eq('id',r.warehouse_receipt_id);await loadSaved(r.warehouse_receipt_id);S.step='checkin';render()}catch(e){alert(e.message);btn.disabled=false;btn.textContent='Create WR & start receiving →'}}

async function reload(){if(S.wr)await loadSaved(S.wr.id);await loadSignatures();render()}
async function loadSignatures(){S.checkinSigned=false;S.checkoutSigned=false;if(!S.tx)return;const{data}=await supabase.from('documents').select('category').eq('transaction_id',S.tx).eq('is_current',true).in('category',['DRIVER_CHECKIN_SIGNATURE','DRIVER_CHECKOUT_SIGNATURE']);for(const d of data||[]){if(d.category==='DRIVER_CHECKIN_SIGNATURE')S.checkinSigned=true;if(d.category==='DRIVER_CHECKOUT_SIGNATURE')S.checkoutSigned=true}}
async function doCheckin(){const carrier=document.getElementById('wros-carrier').value.trim(),driver=document.getElementById('wros-driver').value.trim(),idName=document.getElementById('wros-id-name').value.trim(),rtype=document.getElementById('wros-ref-type').value,ref=document.getElementById('wros-move-ref').value.trim();if(!carrier||!driver||!ref)return alert('Carrier, driver and BOL/PRO/tracking are required.');const entity=S.entities.find(x=>x.name.toLowerCase()===carrier.toLowerCase()),now=new Date().toISOString(),notes=idName?`Name on government ID: ${idName}`:null,payload={organization_id:S.wr.organization_id,warehouse_receipt_id:S.wr.id,direction:'inbound',carrier_id:entity?.id||null,carrier_name_snapshot:carrier,driver_name:driver,driver_id_verified:document.getElementById('wros-id-ok').checked,sta_verified:document.getElementById('wros-sta-ok').checked,time_in:now,trailer_number:document.getElementById('wros-trailer')?.value.trim()||null,tractor_number:document.getElementById('wros-tractor')?.value.trim()||null,seal_number:document.getElementById('wros-seal')?.value.trim()||null,door:document.getElementById('wros-door')?.value.trim()||null,notes,bol_number:rtype==='BOL'?ref:null,pro_number:rtype==='PRO'?ref:null,tracking_number:rtype==='TRACKING'?ref:null};const{data,error}=await supabase.from('warehouse_visits').insert(payload).select('*').single();if(error)throw error;S.visit=data;await supabase.from('warehouse_receipts').update({started_at:now,status:'receiving'}).eq('id',S.wr.id);await reload()}

function hierarchyPath(id){const path=[];let cur=S.cargo.find(x=>x.id===id);while(cur){path.unshift(cur);cur=cur.parent_id?S.cargo.find(x=>x.id===cur.parent_id):null}return path}
function openCargo(id){const x=S.cargo.find(c=>c.id===id);if(!x)return;document.querySelector('.wros-drawer-back')?.remove();document.querySelector('.wros-drawer')?.remove();const path=hierarchyPath(id),linked=S.parts.find(p=>p.id===x.inventory_item_id);document.body.insertAdjacentHTML('beforeend',`<div class="wros-drawer-back"></div><aside class="wros-drawer"><div class="wros-drawer-head"><div><div class="eyebrow">${x.parent_id?'CONTAINED CARGO':'HANDLING UNIT'}</div><h2>${esc(x.description||x.package_type)}</h2></div><button class="secondary" id="wros-close-cargo">Done</button></div><div class="wros-path">${path.map((n,d)=>`<button class="wros-node ${n.id===id?'active':''}" style="--depth:${d}" data-path="${n.id}"><b>${esc(n.description||n.package_type)}</b><small>${d?'Contained level '+d:'Handling level'} · ${esc(n.package_type||'')}</small></button>`).join('')}</div><datalist id="wros-parts">${partOptions()}</datalist><div class="wros-grid"><label class="wros-field"><span>Package type</span><select id="wros-c-type">${TYPES.map(t=>`<option ${t===x.package_type?'selected':''}>${t}</option>`).join('')}</select></label><label class="wros-field"><span>Quantity</span><input id="wros-c-qty" type="number" min="1" value="${x.quantity||1}"></label><div class="wros-field"><span>Count unit</span><div class="wros-select" id="wros-c-uom">${esc(TYPE_UOM[x.package_type]||x.uom||'EA')} · derived from package type</div></div><label class="wros-field"><span>Description</span><input id="wros-c-desc" value="${esc(x.description||'')}"></label><label class="wros-field span2"><span>Part / SKU</span><input id="wros-c-part" list="wros-parts" value="${esc(linked?partLabel(linked):(x.part_number||x.sku||''))}" placeholder="Type part #, SKU or description…"><div class="wros-inline-note" id="wros-part-note">${linked?'Linked automatically to saved Part Master':'Choose an existing part or create one if there is no match.'}</div></label><label class="wros-field"><span>Gross weight (lb)</span><input id="wros-c-weight" type="number" min="0" step="any" value="${x.weight_lb??''}"></label><label class="wros-field"><span>Length (in)</span><input id="wros-c-l" type="number" min="0" step="any" value="${x.length_in??''}"></label><label class="wros-field"><span>Width (in)</span><input id="wros-c-w" type="number" min="0" step="any" value="${x.width_in??''}"></label><label class="wros-field"><span>Height (in)</span><input id="wros-c-h" type="number" min="0" step="any" value="${x.height_in??''}"></label><label class="wros-field"><span>Lot</span><input id="wros-c-lot" value="${esc(x.lot_number||'')}"></label><label class="wros-field"><span>Serial</span><input id="wros-c-serial" value="${esc(x.serial_number||'')}"></label></div><div class="wros-quick" style="margin-top:12px"><button class="secondary" id="wros-c-photo">📷 Photo set</button><button class="secondary" id="wros-c-create-part">＋ New part / SKU</button><button class="secondary" id="wros-c-child">＋ Add contained level</button><button class="secondary" id="wros-c-copy">Duplicate</button></div><div class="wros-live" id="wros-live"></div></aside>`);const type=document.getElementById('wros-c-type'),part=document.getElementById('wros-c-part');const updateMath=()=>{const q=Number(document.getElementById('wros-c-qty').value||1),g=Number(document.getElementById('wros-c-weight').value||0),l=Number(document.getElementById('wros-c-l').value||0),w=Number(document.getElementById('wros-c-w').value||0),h=Number(document.getElementById('wros-c-h').value||0),cbm=l&&w&&h?l*w*h*0.000016387064*q:0,dim=l&&w&&h?l*w*h/166*q:0,charge=Math.max(g,dim);document.getElementById('wros-live').innerHTML=`<div><span>Qty</span><b>${q}</b></div><div><span>Volume</span><b>${cbm.toFixed(4)} CBM</b></div><div><span>Dim wt</span><b>${dim.toFixed(1)} LB</b></div><div><span>Chargeable</span><b>${charge.toFixed(1)} LB</b></div>`};['wros-c-qty','wros-c-weight','wros-c-l','wros-c-w','wros-c-h'].forEach(i=>document.getElementById(i).oninput=updateMath);updateMath();type.onchange=()=>{document.getElementById('wros-c-uom').textContent=`${TYPE_UOM[type.value]||'EA'} · derived from package type`};part.oninput=()=>{const p=findPart(part.value);document.getElementById('wros-part-note').textContent=p?'Will link automatically to this Part Master':'No exact saved part — create a new Part Master if needed.'};document.querySelectorAll('[data-path]').forEach(b=>b.onclick=async()=>{await saveCargo(id,false);openCargo(b.dataset.path)});document.querySelector('.wros-drawer-back').onclick=()=>saveCargo(id,true);document.getElementById('wros-close-cargo').onclick=()=>saveCargo(id,true);document.getElementById('wros-c-photo').onclick=()=>window.NodaraWRCamera?.open({cargoId:id,draft:false});document.getElementById('wros-c-create-part').onclick=()=>openPartDrawer(id,part.value);document.getElementById('wros-c-child').onclick=async()=>{await saveCargo(id,false);await addChild(id)};document.getElementById('wros-c-copy').onclick=async()=>{await saveCargo(id,false);await duplicateCargo(id)} }
function findPart(v){const q=String(v||'').trim().toLowerCase();return S.parts.find(p=>partLabel(p).toLowerCase()===q||String(p.part_number||'').toLowerCase()===q||String(p.sku||'').toLowerCase()===q)}
async function saveCargo(id,close=true){const x=S.cargo.find(c=>c.id===id);if(!x)return;const type=document.getElementById('wros-c-type').value,p=findPart(document.getElementById('wros-c-part').value),values={package_type:type,uom:TYPE_UOM[type]||'EA',quantity:Math.max(1,Number(document.getElementById('wros-c-qty').value||1)),description:document.getElementById('wros-c-desc').value.trim()||null,weight_lb:num(document.getElementById('wros-c-weight').value),length_in:num(document.getElementById('wros-c-l').value),width_in:num(document.getElementById('wros-c-w').value),height_in:num(document.getElementById('wros-c-h').value),lot_number:document.getElementById('wros-c-lot').value.trim()||null,serial_number:document.getElementById('wros-c-serial').value.trim()||null,inventory_item_id:p?.id||null,part_number:p?.part_number||null,sku:p?.sku||null,updated_at:new Date().toISOString()};const{error}=await supabase.from('cargo_units').update(values).eq('id',id);if(error)return alert(error.message);Object.assign(x,values);if(close){document.querySelector('.wros-drawer-back')?.remove();document.querySelector('.wros-drawer')?.remove();render()}}
function treeNode(id){const x=S.cargo.find(c=>c.id===id);return{type:x.package_type||'PIECE',quantity:Number(x.quantity||1),description:x.description||null,inventory_item_id:x.inventory_item_id||null,part_number:x.part_number||null,sku:x.sku||null,uom:x.uom||TYPE_UOM[x.package_type]||'EA',weight_lb:x.weight_lb??null,length_in:x.length_in??null,width_in:x.width_in??null,height_in:x.height_in??null,lot_number:x.lot_number||null,serial_number:x.serial_number||null,warehouse_location_id:rootOf(x)?.warehouse_location_id||null,metadata:x.metadata||{},condition:'good',children:children(id).map(c=>treeNode(c.id))}}
async function addChild(parentId){const node={type:'BOX',quantity:1,description:'BOX',uom:'BOX',condition:'good',children:[]},{error}=await supabase.rpc('insert_wr_cargo_tree_core',{p_org:S.wr.organization_id,p_job:S.wr.job_id,p_wr:S.wr.id,p_parent:parentId,p_node:node,p_path:S.wr.receipt_number,p_location:rootOf(S.cargo.find(x=>x.id===parentId))?.warehouse_location_id||null});if(error)return alert(error.message);await reload();const parent=S.cargo.find(x=>x.id===parentId),child=children(parentId).at(-1);if(child)openCargo(child.id);else if(parent)openCargo(parent.id)}
async function duplicateCargo(id){const x=S.cargo.find(c=>c.id===id);if(!x)return;const{error}=await supabase.rpc('insert_wr_cargo_tree_core',{p_org:S.wr.organization_id,p_job:S.wr.job_id,p_wr:S.wr.id,p_parent:x.parent_id||null,p_node:treeNode(id),p_path:S.wr.receipt_number,p_location:rootOf(x)?.warehouse_location_id||null});if(error)return alert(error.message);await reload()}
function openPartDrawer(cargoId,seed=''){document.querySelector('.wros-part-mini')?.remove();const el=document.createElement('div');el.className='wros-drawer-back wros-part-mini';el.innerHTML=`<aside class="wros-drawer"><div class="wros-drawer-head"><div><div class="eyebrow">PART MASTER</div><h2>Create & link</h2></div><button class="secondary" data-close>×</button></div><div class="wros-grid"><label class="wros-field"><span>Part number</span><input id="wros-p-part" value="${esc(seed)}"></label><label class="wros-field"><span>SKU</span><input id="wros-p-sku"></label><label class="wros-field span2"><span>Description</span><input id="wros-p-desc"></label><label class="wros-field"><span>Base UOM</span><input id="wros-p-uom" value="EA"></label><label class="wros-field"><span>Barcode</span><input id="wros-p-barcode"></label></div><button class="primary" id="wros-p-save" style="width:100%;margin-top:14px">Save & link part</button></aside>`;document.body.appendChild(el);el.querySelector('[data-close]').onclick=()=>el.remove();document.getElementById('wros-p-save').onclick=async()=>{try{const p=await createInventoryItemQuick({part_number:document.getElementById('wros-p-part').value,sku:document.getElementById('wros-p-sku').value,description:document.getElementById('wros-p-desc').value,base_uom:document.getElementById('wros-p-uom').value||'EA',barcode:document.getElementById('wros-p-barcode').value,entity_id:S.customer_id});S.parts.unshift(p);await supabase.from('cargo_units').update({inventory_item_id:p.id,part_number:p.part_number||null,sku:p.sku||null}).eq('id',cargoId);el.remove();await reload();openCargo(cargoId)}catch(e){alert(e.message)}}}

async function addException(){const type=prompt(`Exception type:\n${EXCEPTIONS.map(x=>x[0]).join(', ')}`,'DAMAGE');if(!type)return;const valid=EXCEPTIONS.some(x=>x[0]===type.toUpperCase());if(!valid)return alert('Choose a valid exception type.');const note=prompt('Describe the discrepancy / condition','')||'';const{data:{user}}=await supabase.auth.getUser();const{error}=await supabase.from('operational_flags').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:S.wr.id,flag_type:type.toUpperCase(),severity:['DAMAGE','HOLD','SHORTAGE','SEAL_DISCREPANCY'].includes(type.toUpperCase())?'warning':'info',active:true,source:'manual',notes:note,created_by:user?.id||null});if(error)return alert(error.message);await reload();if(type.toUpperCase()==='DAMAGE'&&confirm('Take damage photos now?'))window.NodaraWRCamera?.open({cargoId:S.selectedCargo?.id||roots()[0]?.id||null,draft:false})}
async function finishUnload(){if(!S.visit?.id)return alert('Check in the driver first.');if(!confirm('Mark unloading / receiving complete?'))return;const now=new Date().toISOString();await supabase.from('warehouse_visits').update({operation_started_at:S.visit.operation_started_at||S.visit.time_in||now,operation_completed_at:now}).eq('id',S.visit.id);S.step='evidence';await reload()}

async function uploadFiles(files){if(!S.tx)return;for(const file of files){const path=`${S.wr.organization_id}/${S.tx}/transaction/${crypto.randomUUID()}_${String(file.name||'file').replace(/[^a-zA-Z0-9._-]/g,'_')}`;const{error:up}=await supabase.storage.from('nodara-documents').upload(path,file,{contentType:file.type||undefined,upsert:false});if(up)throw up;const{error}=await supabase.rpc('nodara_register_document',{p_transaction_id:S.tx,p_document_type:'OTHER',p_storage_path:path,p_file_name:file.name,p_mime_type:file.type||null,p_cargo_object_id:null,p_entity_id:null,p_template_id:null,p_display_name:file.name,p_document_number:null,p_category:'DOCUMENT',p_link_role:'SUPPORTING',p_source:'USER',p_status:'ACTIVE',p_notes:null,p_metadata:{file_size:file.size},p_provenance:{source_type:'USER',surface:'WR_RECEIVING_OS'}});if(error)throw error}await reload()}

async function hasSig(kind){if(!S.tx)return false;const cat=kind==='checkin'?'DRIVER_CHECKIN_SIGNATURE':'DRIVER_CHECKOUT_SIGNATURE';const{data}=await supabase.from('documents').select('id').eq('transaction_id',S.tx).eq('category',cat).eq('is_current',true).limit(1);return !!data?.length}
async function sign(kind){window.NodaraWRSignature?.open({kind,onSaved:async()=>{await loadSignatures();render()}})}
async function checkout(){if(!S.checkoutSigned){await sign('checkout');return}if(!confirm('Check out driver and record time out now?'))return;const now=new Date().toISOString();const{error}=await supabase.from('warehouse_visits').update({time_out:now}).eq('id',S.visit.id);if(error)return alert(error.message);S.step='putaway';await reload()}

async function assignLocation(cargoId,locationId){if(!locationId)return alert('Choose or scan a location.');const{error}=await supabase.from('cargo_units').update({current_location_id:locationId,warehouse_location_id:locationId,updated_at:new Date().toISOString()}).eq('id',cargoId);if(error)return alert(error.message);S.selectedCargo=S.cargo.find(x=>x.id===cargoId)||null;await reload()}
function scanCargo(){window.nodaraScanTask?.({title:'Scan cargo label',hint:'Scan NODARA handling-unit / UIN label',onScan:raw=>{const q=String(raw||'').trim().toLowerCase(),x=roots().find(c=>[c.handling_unit_code,c.uin,c.part_number,c.sku].some(v=>String(v||'').toLowerCase()===q));if(!x)return false;S.selectedCargo=x;render();return true}})}
function scanLocation(){if(!S.selectedCargo)return alert('Select or scan a cargo handling unit first.');window.nodaraScanTask?.({title:'Scan put-away location',hint:'Scan rack / bay / position label',onScan:async raw=>{const q=String(raw||'').trim().toLowerCase(),l=S.locations.find(x=>String(x.code||'').toLowerCase()===q||String(x.id||'').toLowerCase()===q);if(!l)return false;await assignLocation(S.selectedCargo.id,l.id);return true}})}

async function ensurePDF(){if(window.jspdf?.jsPDF&&window.jspdf?.autoTable)return window.jspdf.jsPDF;await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';s.onload=res;s.onerror=rej;document.head.appendChild(s)});await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.4/dist/jspdf.plugin.autotable.min.js';s.onload=res;s.onerror=rej;document.head.appendChild(s)});return window.jspdf.jsPDF}
async function wrPDF(){const JS=await ensurePDF(),doc=new JS({unit:'pt',format:'letter'}),customer=S.entities.find(x=>x.id===S.customer_id),m=cargoMetrics(),v=S.visit||{};doc.setFontSize(18);doc.text('WAREHOUSE RECEIPT',40,45);doc.setFontSize(11);doc.text(S.wr.receipt_number,40,64);doc.setFontSize(10);doc.text(`Customer: ${customer?.name||''}`,40,88);doc.text(`Reference: ${S.customer_ref||''}`,40,103);doc.text(`Received: ${fmt(S.wr.started_at||S.wr.created_at)}`,40,118);doc.text(`Carrier: ${v.carrier_name_snapshot||''}`,300,88);doc.text(`Driver: ${v.driver_name||''}`,300,103);doc.text(`BOL/PRO/Tracking: ${v.bol_number||v.pro_number||v.tracking_number||''}`,300,118);doc.autoTable({startY:145,head:[['Cargo','Qty','Part/SKU','Weight','Dimensions','Location']],body:flat().map(({x,depth})=>{const l=S.locations.find(z=>z.id===(rootOf(x)?.current_location_id||rootOf(x)?.warehouse_location_id));return[`${'  '.repeat(depth)}${x.description||x.package_type}`,`${x.quantity||0} ${x.uom||''}`,x.part_number||x.sku||'',x.weight_lb?`${x.weight_lb} lb`:'',[x.length_in,x.width_in,x.height_in].every(Boolean)?`${x.length_in}×${x.width_in}×${x.height_in} in`:'',l?.code||'']})});let y=doc.lastAutoTable.finalY+18;doc.text(`Handling units: ${m.handling}    Gross weight: ${m.weight} LB    Volume: ${m.volume.toFixed(4)} CBM`,40,y);y+=16;if(S.flags.length){doc.text(`Exceptions: ${S.flags.map(x=>x.flag_type).join(', ')}`,40,y);y+=16}doc.text(`Evidence / documents: ${S.docs.length}`,40,y);doc.save(`${S.wr.receipt_number}.pdf`)}
function printLabels(){const tops=roots(),w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print labels.');w.document.write(`<html><head><title>${esc(S.wr.receipt_number)} labels</title><style>@page{size:4in 6in;margin:.18in}body{font-family:Arial;margin:0}.label{width:3.64in;height:5.55in;page-break-after:always;border:1px solid #111;padding:.15in;box-sizing:border-box}.wr{font-size:13px}.code{font-size:28px;font-weight:800;margin:12px 0}.meta{font-size:14px;margin:8px 0}.big{font-size:22px;font-weight:700}.loc{margin-top:18px;font-size:20px}.foot{position:absolute;bottom:.25in}</style></head><body>${tops.map(x=>{const loc=S.locations.find(l=>l.id===(x.current_location_id||x.warehouse_location_id));return `<div class="label"><div class="wr">NODARA · ${esc(S.wr.receipt_number)}</div><div class="code">${esc(x.handling_unit_code||x.uin||x.id.slice(0,8))}</div><div class="big">${esc(x.description||x.package_type)}</div><div class="meta">${Number(x.quantity||0)} ${esc(x.uom||'')} · ${esc(x.package_type||'')}</div><div class="meta">${esc(x.part_number||x.sku||'')}</div><div class="meta">${x.weight_lb?`${x.weight_lb} LB`:''}</div><div class="loc">${loc?`LOCATION ${esc(loc.code)}`:'LOCATION _________'}</div><svg class="barcode" data-code="${esc(x.handling_unit_code||x.uin||x.id)}"></svg></div>`}).join('')}<script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script>window.onload=()=>{document.querySelectorAll('.barcode').forEach(x=>JsBarcode(x,x.dataset.code,{format:'CODE128',width:2,height:70,displayValue:false}));setTimeout(()=>print(),300)}<\/script></body></html>`);w.document.close()}
async function completeWR(){const unresolved=[];if(!S.visit?.time_out)unresolved.push('driver not checked out');if(roots().some(x=>!(x.current_location_id||x.warehouse_location_id)))unresolved.push('cargo without put-away location');if(unresolved.length&&!confirm(`Complete with unresolved items?\n• ${unresolved.join('\n• ')}`))return;const now=new Date().toISOString();const{error}=await supabase.from('warehouse_receipts').update({status:'completed',completed_at:now}).eq('id',S.wr.id);if(error)return alert(error.message);await reload()}

function bind(){main.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(b.dataset.step));main.querySelectorAll('[data-draft-flag]').forEach(b=>b.onclick=()=>{const k=b.dataset.draftFlag,i=S.draftFlags.indexOf(k);if(i>=0)S.draftFlags.splice(i,1);else S.draftFlags.push(k);render()});document.getElementById('wros-start')?.addEventListener('click',startReceiving);document.getElementById('wros-cancel')?.addEventListener('click',()=>window.nodaraWRList?.());document.getElementById('wros-checkin')?.addEventListener('click',()=>doCheckin().catch(e=>alert(e.message)));document.querySelectorAll('[data-sign]').forEach(b=>b.onclick=()=>sign(b.dataset.sign));document.querySelectorAll('[data-scan-doc]').forEach(b=>b.onclick=()=>window.NodaraWRScanner?.open({draft:false,category:b.dataset.scanDoc||'SCANNED_DOCUMENT'}));document.getElementById('wros-add-root')?.addEventListener('click',async()=>{const node={type:'PALLET',quantity:1,description:'PALLET',uom:'PLT',condition:'good',children:[]},{error}=await supabase.rpc('insert_wr_cargo_tree_core',{p_org:S.wr.organization_id,p_job:S.wr.job_id,p_wr:S.wr.id,p_parent:null,p_node:node,p_path:S.wr.receipt_number,p_location:null});if(error)return alert(error.message);await reload();openCargo(roots().at(-1).id)});main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openCargo(b.dataset.edit));main.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>duplicateCargo(b.dataset.copy));main.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>addChild(b.dataset.child));main.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>window.NodaraWRCamera?.open({cargoId:b.dataset.photo,draft:false}));document.getElementById('wros-exception')?.addEventListener('click',addException);document.getElementById('wros-unload-complete')?.addEventListener('click',finishUnload);document.getElementById('wros-camera')?.addEventListener('click',()=>window.NodaraWRCamera?.open({cargoId:S.selectedCargo?.id||roots()[0]?.id||null,draft:false}));document.getElementById('wros-scan')?.addEventListener('click',()=>window.NodaraWRScanner?.open({draft:false}));document.getElementById('wros-upload')?.addEventListener('click',()=>document.getElementById('wros-upload-input').click());document.getElementById('wros-upload-input')?.addEventListener('change',e=>uploadFiles([...e.target.files]).catch(x=>alert(x.message)));document.getElementById('wros-checkout')?.addEventListener('click',checkout);document.getElementById('wros-labels')?.addEventListener('click',printLabels);document.getElementById('wros-labels2')?.addEventListener('click',printLabels);document.getElementById('wros-scan-cargo')?.addEventListener('click',scanCargo);document.getElementById('wros-scan-location')?.addEventListener('click',scanLocation);main.querySelectorAll('[data-select-cargo]').forEach(b=>b.onclick=()=>{S.selectedCargo=S.cargo.find(x=>x.id===b.dataset.selectCargo);render()});main.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignLocation(b.dataset.assign,main.querySelector(`[data-location-for="${CSS.escape(b.dataset.assign)}"]`).value));document.getElementById('wros-pdf')?.addEventListener('click',()=>wrPDF().catch(e=>alert(e.message)));document.getElementById('wros-pdfbar')?.addEventListener('click',()=>wrPDF().catch(e=>alert(e.message)));document.getElementById('wros-complete')?.addEventListener('click',completeWR);document.getElementById('wros-prev')?.addEventListener('click',()=>{const i=STEPS.findIndex(x=>x[0]===S.step);if(i>0)setStep(STEPS[i-1][0])});document.getElementById('wros-next')?.addEventListener('click',()=>{const i=STEPS.findIndex(x=>x[0]===S.step);if(i<STEPS.length-1)setStep(STEPS[i+1][0])});document.getElementById('wros-skip')?.addEventListener('click',()=>{const i=STEPS.findIndex(x=>x[0]===S.step);if(i<STEPS.length-1)setStep(STEPS[i+1][0])});document.getElementById('wros-list')?.addEventListener('click',()=>window.nodaraWRList?.())}

export async function openNewWarehouseReceipt(){S={wr:null,job:null,tx:null,visit:null,cargo:[],docs:[],flags:[],entities:[],parts:[],locations:[],customer_id:'',customer_name:'',customer_ref:'',description:'',start_type:'PALLET',start_qty:1,draftFlags:[],step:'setup',selectedCargo:null,checkinSigned:false,checkoutSigned:false};await loadReferenceData();render()}
export async function openWarehouseReceipt(id){S={wr:null,job:null,tx:null,visit:null,cargo:[],docs:[],flags:[],entities:[],parts:[],locations:[],draftFlags:[],step:'checkin',selectedCargo:null,checkinSigned:false,checkoutSigned:false};await loadReferenceData();await loadSaved(id);await loadSignatures();render()}
window.nodaraOpenCanonicalWR=openWarehouseReceipt;
window.nodaraNewCanonicalWR=openNewWarehouseReceipt;
document.addEventListener('nodara:wr-evidence-updated',()=>S?.wr&&reload().catch(console.warn));document.addEventListener('nodara:wr-signature-saved',()=>S?.wr&&reload().catch(console.warn));
